import{_ as n,o as a,c as t,a2 as r}from"./chunks/framework.DaGSOal_.js";const f=JSON.parse('{"title":"N","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/n.md","filePath":"glossaire-a-z/n.md"}'),i={name:"glossaire-a-z/n.md"};function o(s,e,u,l,d,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h1><h2 id="nakamoto-coefficient-fr-coefficient-de-nakamoto" tabindex="-1">Nakamoto Coefficient (fr : Coefficient de Nakamoto) <a class="header-anchor" href="#nakamoto-coefficient-fr-coefficient-de-nakamoto" aria-label="Permalink to &quot;Nakamoto Coefficient (fr : Coefficient de Nakamoto)&quot;">​</a></h2><p>Une mesure de la décentralisation d’une blockchain qui identifie le nombre minimal d’entités capables de s’entendre pour perturber le réseau ou compromettre son fonctionnement. Un coefficient plus élevé indique généralement une meilleure résistance à la centralisation.</p><h2 id="native-token-fr-jeton-natif" tabindex="-1">Native Token (fr : Jeton natif) <a class="header-anchor" href="#native-token-fr-jeton-natif" aria-label="Permalink to &quot;Native Token (fr : Jeton natif)&quot;">​</a></h2><p>Un jeton intégré au registre d’une blockchain, dont la création et le transfert ne nécessitent pas de contrat intelligent dédié. Cardano prend en charge les actifs natifs aux côtés de l’ada, permettant aux utilisateurs de créer et de transférer leurs propres jetons directement sur la blockchain.</p><h2 id="net-change-limit-fr-limite-de-variation-nette" tabindex="-1">Net Change Limit (fr : Limite de variation nette) <a class="header-anchor" href="#net-change-limit-fr-limite-de-variation-nette" aria-label="Permalink to &quot;Net Change Limit (fr : Limite de variation nette)&quot;">​</a></h2><p>Une limite constitutionnelle qui plafonne le montant net d’ada que la trésorerie de Cardano peut verser sur une période définie. Les représentants délégués (<em>Delegated Representatives</em>, DReps) participent à la décision concernant cette limite dans le cadre de la gouvernance du réseau.</p><h2 id="network-fr-reseau" tabindex="-1">Network (fr : Réseau) <a class="header-anchor" href="#network-fr-reseau" aria-label="Permalink to &quot;Network (fr : Réseau)&quot;">​</a></h2><p>Un ensemble d’ordinateurs interconnectés qui échangent des données et des ressources. Dans une blockchain, le réseau est constitué de nœuds distribués qui maintiennent un registre partagé et utilisent un mécanisme de consensus. Sur Cardano, une architecture pair-à-pair permet aux nœuds, notamment ceux exploités par les opérateurs de pools de staking, de participer à la propagation des transactions et à la production des blocs.</p><h2 id="networking-layer-fr-couche-reseau" tabindex="-1">Networking Layer (fr : Couche réseau) <a class="header-anchor" href="#networking-layer-fr-couche-reseau" aria-label="Permalink to &quot;Networking Layer (fr : Couche réseau)&quot;">​</a></h2><p>La couche technique qui permet aux nœuds d’une blockchain de communiquer entre eux. Elle comprend les mécanismes de communication pair-à-pair nécessaires à l’échange de données et à la coordination entre les participants du réseau.</p><h2 id="node-fr-nœud" tabindex="-1">Node (fr : Nœud) <a class="header-anchor" href="#node-fr-nœud" aria-label="Permalink to &quot;Node (fr : Nœud)&quot;">​</a></h2><p>Un ordinateur ou un appareil exécutant un logiciel blockchain et participant au fonctionnement du réseau. Selon son rôle, un nœud peut valider des transactions, relayer des données ou produire des blocs. Sur Cardano, les nœuds peuvent notamment fonctionner comme producteurs de blocs, relais ou participants qui ne produisent pas directement de blocs.</p><h2 id="non-fungible-token-nft-fr-jeton-non-fongible" tabindex="-1">Non-Fungible Token (NFT) (fr : Jeton non fongible) <a class="header-anchor" href="#non-fungible-token-nft-fr-jeton-non-fongible" aria-label="Permalink to &quot;Non-Fungible Token (NFT) (fr : Jeton non fongible)&quot;">​</a></h2><p>Un jeton numérique unique représentant un actif spécifique et qui n’est pas interchangeable à l’identique avec un autre jeton. Sur Cardano, les NFT peuvent être représentés par des actifs natifs enregistrés sur la blockchain. Le jeton ne garantit pas, à lui seul, les droits d’auteur ou la propriété juridique du contenu associé.</p><h2 id="nothing-at-stake-fr-probleme-du-«-rien-a-perdre-»" tabindex="-1">Nothing-at-Stake (fr : Problème du « rien à perdre ») <a class="header-anchor" href="#nothing-at-stake-fr-probleme-du-«-rien-a-perdre-»" aria-label="Permalink to &quot;Nothing-at-Stake (fr : Problème du « rien à perdre »)&quot;">​</a></h2><p>Un risque associé aux mécanismes de preuve d’enjeu (<em>Proof of Stake</em>) dans lequel des validateurs peuvent signer plusieurs forks concurrents, car cela ne leur impose pas nécessairement de coût supplémentaire. Ce comportement peut compliquer le choix de la chaîne légitime.</p>',17)])])}const m=n(i,[["render",o]]);export{f as __pageData,m as default};
